sys_script_include.script:
var LabRequestNotifier = Class.create();
LabRequestNotifier.prototype = {
    initialize: function () {
        this.SCOPE = 'x_2223823_apollo_0';
        // The lab staff group of a hospital is named: <hospital name> + this suffix, e.g. 'Apollo Jaipur - Lab Staff'.
        this.LAB_GROUP_SUFFIX = ' - Lab Staff';
    },

    notifyRequested: function (result) {
        this._notifyLabTeam(result);
        if (result.getValue('urgent') == '1' || result.getValue('urgent') == 'true') {
            this._notifyDoctor(result);
        }
    },

    // lab staff group of the result's hospital
    _notifyLabTeam: function (result) {
        var hosp = result.hospital.getRefRecord();
        if (!hosp.isValidRecord()) { return; }
        var groupName = hosp.getValue('name') + this.LAB_GROUP_SUFFIX;
        var ids = this._groupMembers(groupName);
        if (!ids.length) {
            gs.error('FL-04: no members found in group "' + groupName + '". The lab team was not notified.');
            return;
        }
        gs.eventQueue(this.SCOPE + '.lab_request_created', result, ids.join(','), result.lab_test.getDisplayValue());
    },

    // urgent only: the doctor of the appointment or admission chosen on the Lab Test Request
    _notifyDoctor: function (result) {
        var doctorUser = this._doctorUser(result);
        if (!doctorUser) {
            gs.error('FL-04: urgent lab result ' + result.getUniqueValue() + ': no doctor found from the request, so no doctor was notified.');
            return;
        }
        gs.eventQueue(this.SCOPE + '.lab_urgent_request', result, doctorUser, result.patient.getDisplayValue());
    },

    // type = Appointment: Appointment.doctor.  type = Admission: Admission.admitting_doctor.  Then Doctor.user.
    _doctorUser: function (result) {
        var ritm = result.request.getRefRecord();
        if (!ritm.isValidRecord()) { return ''; }

        var type = this._var(ritm, ['type']).toLowerCase();
        var doctorId = '';
        if (type == 'appointment') {
            var apptId = this._var(ritm, ['appointment']);
            if (apptId) {
                var appt = new GlideRecord(this.SCOPE + '_appointment');
                if (appt.get(apptId)) { doctorId = appt.getValue('doctor'); }
            }
        } else if (type == 'admission') {
            var admId = this._var(ritm, ['admission']);
            if (admId) {
                var adm = new GlideRecord(this.SCOPE + '_admission');
                if (adm.get(admId)) { doctorId = adm.getValue('admitting_doctor'); }
            }
        }
        if (!doctorId) { return ''; }

        var doc = new GlideRecord(this.SCOPE + '_doctor');
        return doc.get(doctorId) ? doc.getValue('user') : '';
    },

    // catalog variable by name; for a "type" select box it returns the label, for a reference the sys_id
    _var: function (ritm, names) {
        for (var i = 0; i < names.length; i++) {
            var v = ritm.variables[names[i]];
            if (v === undefined || v === null) { v = ritm.variables[this.SCOPE + '_' + names[i]]; }
            if (v !== undefined && v !== null && v.toString() !== '') {
                var label = (v.getDisplayValue ? v.getDisplayValue() : '').toString();
                return names[i] == 'type' && label ? label : v.toString();
            }
        }
        return '';
    },

    _groupMembers: function (groupName) {
        var ids = [];
        var g = new GlideRecord('sys_user_group');
        g.addQuery('name', groupName);
        g.query();
        if (!g.next()) { return ids; }
        var m = new GlideRecord('sys_user_grmember');
        m.addQuery('group', g.getUniqueValue());
        m.query();
        while (m.next()) { ids.push(m.getValue('user')); }
        return ids;
    },

    type: 'LabRequestNotifier'
};
